// ---- the map functions ----------------------------------------------------------------
// reads n bits (n <= 16) starting at bit b of a PROGMEM array
uint16_t arenaMapBits(const uint8_t *d, uint32_t b, uint8_t n)
{
  uint16_t v = 0;
  for (uint8_t s = 0; n; s += 8)
  {
    uint8_t c = n > 8 ? 8 : n;
    v |= (uint16_t)((pgm_read_word(d + (b >> 3)) >> (b & 7)) & ((1u << c) - 1)) << s;
    b += c;
    n -= c;
  }
  return v;
}

// the map part at part position px, py
uint8_t arenaMapGetPart(uint8_t px, uint8_t py)
{
  return arenaMapBits(arenaMapWorld, ((uint16_t)py * ARENAMAP_PARTS_W + px) * ARENAMAP_BITS_P, ARENAMAP_BITS_P);
}

// tile lx, ly of a shared block
uint8_t arenaMapBlockTile(uint8_t idx, uint8_t lx, uint8_t ly)
{
  const uint8_t *g = arenaMapBlockGroups + (ARENAMAP_BLOCK_GROUPS - 1) * 4;
  while (pgm_read_byte(g) > idx) g -= 4;
  uint8_t bits = pgm_read_byte(g + 1);
  uint32_t cell = (uint32_t)(idx - pgm_read_byte(g)) * (ARENAMAP_BLOCK_W * ARENAMAP_BLOCK_H) + ly * ARENAMAP_BLOCK_W + lx;
  return arenaMapBits(arenaMapBlockData + pgm_read_word(g + 2), cell * bits, bits);
}

// tile lx, ly (inside the part) of a map part
uint8_t arenaMapPartTile(uint8_t part, uint8_t lx, uint8_t ly)
{
  uint8_t b = arenaMapBits(arenaMapPartBlocks, ((uint32_t)part * 16 + (ly / ARENAMAP_BLOCK_H) * 4 + lx / ARENAMAP_BLOCK_W) * ARENAMAP_BITS_B, ARENAMAP_BITS_B);
  return arenaMapBlockTile(b, lx % ARENAMAP_BLOCK_W, ly % ARENAMAP_BLOCK_H);
}

// the tile at tile position x, y (x and y are never negative)
uint8_t arenaMapGetTile(uint16_t x, uint16_t y)
{
  if (x >= ARENAMAP_WIDTH || y >= ARENAMAP_HEIGHT) return ARENAMAP_OUTSIDE_TILE;
  return arenaMapPartTile(arenaMapGetPart(x / ARENAMAP_PART_W, y / ARENAMAP_PART_H), x % ARENAMAP_PART_W, y % ARENAMAP_PART_H);
}

bool arenaMapIsSolid(uint8_t tile)
{
  return tile >= ARENAMAP_FIRST_SOLID;
}

bool arenaMapIsSolidAt(uint16_t x, uint16_t y)
{
  return arenaMapIsSolid(arenaMapGetTile(x, y));
}

// draws the map on the screen, camX and camY are the top left pixel of the screen in the world
void arenaMapDraw(uint16_t camX, uint16_t camY)
{
  uint16_t tx0 = camX / ARENAMAP_TILE_W, ty0 = camY / ARENAMAP_TILE_H;
  uint8_t sx = camX % ARENAMAP_TILE_W, sy = camY % ARENAMAP_TILE_H;
  uint8_t cols = 128 / ARENAMAP_TILE_W + (sx ? 1 : 0), rows = 64 / ARENAMAP_TILE_H + (sy ? 1 : 0);
  uint8_t part = 0, lastX = 255, lastY = 255;
  for (uint8_t j = 0; j < rows; j++)
  {
    for (uint8_t i = 0; i < cols; i++)
    {
      uint16_t x = tx0 + i, y = ty0 + j;
      uint8_t tile = ARENAMAP_OUTSIDE_TILE;
      if (x < ARENAMAP_WIDTH && y < ARENAMAP_HEIGHT)
      {
        uint8_t px = x / ARENAMAP_PART_W, py = y / ARENAMAP_PART_H;
        if (px != lastX || py != lastY)
        {
          part = arenaMapGetPart(px, py);
          lastX = px;
          lastY = py;
        }
        tile = arenaMapPartTile(part, x % ARENAMAP_PART_W, y % ARENAMAP_PART_H);
      }
      Sprites::drawOverwrite((int16_t)(i * ARENAMAP_TILE_W) - sx, (int16_t)(j * ARENAMAP_TILE_H) - sy, arenaMapTiles, tile);
    }
  }
}

